			q = { "How do I get guild chat in its own tab?", "My Guild Master chat tab stopped getting the channels" },
			text = "Type /gmf chatwindow tab, then right-click General, Create New Window, name it Guild Master: the channels move there. If they move back after a relog, do it again.",
			long = "Click Add a Guild Master chat tab on the Chat tab (or type /gmf chatwindow tab), then right-click General, Create New Window, and name it Guild Master: the channels move there. Untick other chats in that tab's settings. If the game forgets that choice at login, redo it after a relog." },
		{ id = "feat-channels", topic = "features",
			q = { "How do I talk in guild chat?", "Who can read [{officers}]?", "Is guild chat private?" },
			text = "Talk with /gma, /gmo and /gml. /gmf chat on turns chats on. Not private: never share passwords there.",
			long = "/gma for the everyone chat (labelled with your guild's or network's name), /gmo for [{officers}] ({officers} and up), /gml for [{guildmasters}] (networks only). The chats stay off until you say yes (/gmf chat on). They aren't private: everyone holding your network's key can read all three, so never share passwords." },
		{ id = "feat-chat-off", topic = "features",
			q = { "How do I turn off the /gma spam?", "Can I hide guild chat?" },
			text = "Type /gmf chat off to turn chats off. /gmf mute guild hides one channel. /gmf filter add <word> hides lines with a word.",
			long = "/gmf chat off turns the chats off on your client: nothing shows or sends. Or /gmf mute guild to hide just that channel, or /gmf filter add <word> to hide lines with a word." },
		{ id = "feat-block-terms", topic = "features",
			q = { "How do I hide certain words?", "What does /gmf filter do?" },
			text = "Type /gmf filter add <word> to hide lines with it, on your screen only. /gmf filter shared off ignores the moderators' list.",
			long = "/gmf filter add <word> hides addon lines with that word on your screen only: chats, letters, calls and Voice. The sender isn't blocked. Moderators also keep a shared list; /gmf filter shared off ignores it." },
		{ id = "feat-decrees", topic = "features",
			q = { "What's a {rareCall}?", "How do I send a gathering?" },
			text = "Any member: {rareCall} on a rare target (/gmf rare). {moderators} and {officers}: Gathering (/gmf gather). Add test for a preview only you see.",
			long = "Any member sends a {rareCall} (on a rare enemy in their target: a skull on every map, an alert for the zone and the ones next to it). {moderators} and {officers} send a Gathering (a rally point for 30 minutes). {leaderCall}s and Assemble the Loyal are for the leadership. Others get a local preview; /gmf rare test tries it." },
		{ id = "feat-alert-sounds", topic = "features",
			q = { "How do I turn off the alert sounds?", "Why didn't I get the alert in my dungeon?" },
			text = "Type /gmf sound off for all, or /gmf sound <kind> off. In instances alerts wait; /gmf alerts always shows them at once.",
			long = "/gmf sound off silences them all, or /gmf sound polls off (or another kind) for one. In an instance or while Busy, alerts wait until you're out; /gmf alerts always shows them at once." },
		{ id = "feat-writs", topic = "features",
			q = { "What's a letter from the {leader}?", "How do I answer a letter?" },
			text = "A letter from the {leader} in the {callsTab} tab. {guildmasters} and {officers} can click Acknowledge.",
			long = "A letter from the {leader} in the {callsTab} tab, to the {guildmasters}, to {guildmasters} and {officers}, or to all the {members}. {guildmasters} and {officers} can answer Acknowledge, and the {leader} sees how many did." },
		{ id = "feat-net-off", topic = "features",
			q = { "Someone's lines disappeared", "What's net-off?", "Can moderators hide spammers?" },
			text = "Moderators can hide a character or guild from the network. The {callsTab} tab says who, why, by whom and when.",
			long = "Moderators (the {leader}, the {helpers} and the {moderators}) can hide a character or take a guild off the network for everyone. The {callsTab} tab lists who's hidden, why, by whom and when." },
		{ id = "feat-acts-log", topic = "features",
			q = { "Who opened the portal?", "What's /gmf log?" },
			text = "Type /gmf log: calls, portals and absolutions your client saw, with who did them. Kept on your PC only.",
			long = "What this client saw: calls, portals and the {leader}'s switches, each with who did it. It's on the {callsTab} tab or /gmf log, kept on your computer only and never sent." },
		{ id = "feat-tabards", topic = "features",
			q = { "What's the {tabardsTab} tab?", "What are Loyalists?", "What's Guildmates nearby?" },
			text = "The tabard tab: who wears the guild tabard, never who doesn't. Guildmates nearby and Loyalists live there.",
			long = "{tabardsTab} celebrates the tabard. Guildmates nearby looks at guildmates near you (level, where, tabard); Loyalists were seen in the tabard on 3 days or more. What your own addon saw, never sent. Assemble the Loyal calls everyone together, tabards on." },
		{ id = "feat-musters", topic = "features",
			q = { "What's an officer muster?", "What's /gmf musters?" },
			text = "A quiet 20-minute call to one zone: officers call their guild, the {leader} and the {helpers} every guild. {guildTab} or /gmf musters.",
			long = "An officer muster is a quiet call to one zone for 20 minutes: no alert, no sound, no map pin. A guild's officers call their own guild; the {leader} and the {helpers} call every guild of the network. See them in {guildTab} (Officer musters) or with /gmf musters." },
		{ id = "feat-brief", topic = "features",
			q = { "What's Your week, in five lines?", "What's /gmf brief?" },
			text = "Five things for you: next event, what's open, guildmates online, a partner guild on your layer, your version. /gmf brief.",
			long = "Your week, in five lines ({guildTab}, or /gmf brief): your next event and your signup, what's open now, guildmates online, a partner guild's member on your layer, and whether your add-on is up to date. The Board's The week has the census numbers, the events and the last poll. Nothing is sent." },
		{ id = "feat-hotkey", topic = "features",
			q = { "Is there a key to open the window?", "What's Shift-J?" },
			text = "Shift + your guild key (Shift-J) opens the window when that key is free. Or pick one in Key Bindings, AddOns.",
			long = "Shift + your guild key (Shift-J by default) opens and closes the window, only while that key has no other binding. You can also pick your own key in the game's Key Bindings, under AddOns: Toggle Guild Master Forever. /gmf hotkey off turns the Shift-J shortcut off." },
		{ id = "feat-letters", topic = "features",
			q = { "What's new in this version?", "What's /gmf letters?" },
			text = "After each update a short What's new letter shows once. /gmf letters lists every version's.",
			long = "After the add-on updates, a short letter about what changed shows once, a few seconds after login (after the privacy page, never in combat or a dungeon). /gmf letters lists every version's letter; click one to read it." },
		{ id = "feat-update-peers", topic = "features",
			q = { "Why does chat tell me to update?", "Guild Master Forever is on version X, you are on Y?" },
			text = "Two or more guildmates run a newer Guild Master Forever than you: update it from CurseForge, then restart the game.",
			long = "From 1.2.2, when two or more guildmates' addons say they run a newer version than yours, one line in chat says so, once a login. Update from the CurseForge app, WowUp or the CurseForge page, then restart the game." },
		{ id = "feat-key-locked", topic = "features",
			q = { "Why does it say it's waiting for the network key?", "How do we get the key?" },
			text = "Your add-on hasn't got your guild's key yet. It comes by itself from an officer who is online; nobody types it.",
			long = "The census, chats and map calls travel on a hidden channel sealed with your guild's network key. Your add-on gets it over guild chat from an officer who is online; if nobody in the guild has one yet, the first officer to log in makes it. The key icon in the window's header turns gold once you're on. Until then you see your own guild's roster only." },
		{ id = "feat-patrol", topic = "features",
			q = { "How does the Guildmates nearby patrol work?", "What's /gmf patrol?" },
			text = "Click Guildmates nearby on the {tabardsTab} tab (or /gmf patrol), then walk around: guildmates near you show up, those in the tabard counted.",
			long = "Click Guildmates nearby on the {tabardsTab} tab (or /gmf patrol) and walk around: guildmates near you show up with their level and zone, and those wearing the guild tabard are counted. Nobody is ever listed for not wearing it. Hover a guildmate to see when you last saw them in tabards." },
		{ id = "feat-gear-seen", topic = "features",
			q = { "How do officers save someone's gear?", "What's Gear seen?" },
			text = "Officers: target someone, /gmf gear. It keeps what they wear under Gear seen. Nothing is scored or sent.",
			long = "Officers: target someone in range and type /gmf gear. What they wear is kept under Gear seen on the {tabardsTab} tab, to check later. Nothing is scored or sent." },
		{ id = "feat-throne", topic = "features",
			q = { "What can the {leader} do in the addon?", "What's the {leaderTab} tab?" },
			text = "The {leader}'s tab: Agenda, Court, key rotation. Summon the {guildmasters} and portals are on {guildTab} tab. The {helpers} get some tools.",
			long = "The {leader}'s own tab: their Agenda and week, Hold Court and key rotation. Their other tools sit where they belong: Summon the {guildmasters} and the portal on {guildTab} tab, letters in {callsTab}. The {helpers} can use some of them." },
		{ id = "feat-agenda", topic = "features",
			q = { "I got a popup about a guild event", "What's the {leader}'s Agenda?" },
			text = "The {leader}'s Agenda: a popup with the next guild event, shown on the {censusTab}, with reminders 10 and 1 min before.",
			long = "The {leader} sets the next guild event: everyone gets a popup with what, when and where, sees it on the {censusTab}, and gets reminders 10 minutes and 1 minute before." },
		{ id = "feat-summon-lords", topic = "features",
			q = { "I got 'The {leader} summons the {guildmasters}'", "What's Summon the {guildmasters}?" },
			text = "A roll call for {guildmasters} and {officers}: answer Present or Busy. The {leader} sees who answered.",
			long = "A roll call for {guildmasters} and {officers} online: answer Present or Busy. The {leader} sees who answered and who didn't, and {guildTab} tab marks each of them for a while." },
		{ id = "feat-hold-court", topic = "features",
			q = { "What's Hold Court?", "How do I join the {leader}'s court?" },
			text = "When the {leader} holds a court, players in their zone get a line: one click asks to join the court.",
			long = "When the {leader} opens a court, everyone in their zone gets a line on the {censusTab} and {guildTab} tabs. One click asks to join the court, and they call players from their queue." },
		{ id = "feat-steward-hands", topic = "features",
			q = { "What's one of the {recruiters}?", "Who are the {helpers} of the {leader}?" },
			text = "{recruiters} are the {leader}'s ambassadors: recruiters with the guild rank {recruiters}, in any guild of the network. Join requests reach them first, and they open the portal for new recruits. {helpers} are players they name to run their Agenda, Voice, roll call and portals.",
			long = "{recruiters} are the {leader}'s ambassadors, recruiters only: members of any guild of the network with the guild rank {recruiters}. Recruits asking to join are sent to them first, then to officers; they see the recruits page and open the portal that sends new recruits to a guild, and have no officer tools. {helpers} are players the {leader} names on the {leaderTab} to run their Agenda, {pollsTab}, roll call, inspection and portal in their name." },
		{ id = "feat-vox", topic = "features",
			q = { "What's {pollsTab}?", "How do I vote?" },
			text = "The {leader}'s polls: tick your answer before the timer ends. /gmf polls off keeps them in chat.",
			long = "The {leader}'s polls: 2 to 6 answers, open for a short time. A window pops up with check boxes and a countdown; your vote goes to the {leader}, and everyone sees the result. /gmf polls off keeps questions in chat." },
		{ id = "feat-treasury", topic = "features",
			q = { "What's the Treasury tab?", "How is the treasury balance counted?" },
			text = "The treasury from its keepers' books: gifts by trade or mail count. Everyone sees what the {leader} chooses to show.",
			long = "The {members}'s treasury, from its keepers' books: gold and items given to a keeper by trade or mail are donations. Keepers, the {leader} see it all; everyone else sees what the {leader} chooses to show." },
		{ id = "feat-guild-bank", topic = "features",
			q = { "Can I see the guild of the network bank?", "What's in the home guild's bank?" },
			text = "When the {leader} shows it, the Treasury tab has a snapshot of the home guild's bank, with search.",
			long = "When the {leader} shows the treasury's book, the Treasury tab has a snapshot of the home guild's guild bank, with search and what's gone since the last snapshot. It's a picture: nothing gets moved." },
		{ id = "feat-treasury-requests", topic = "features",
			q = { "How do I ask the treasury for items?", "What's /gmf need?" },
			text = "{guildmasters} and {officers}: /gmf need 10 then shift-click the item. Keepers see it and you're told when it's done.",
			long = "{guildmasters} and {officers}: /gmf need 10 and shift-click the item. The keepers see it on their Treasury tab and mark it done or declined, and you're told. The handover is still a normal trade or mail." },
		{ id = "feat-sister-banks", topic = "features",
			q = { "Can the {leader} see our guild bank?", "What's /gmf bank share?" },
			text = "Only with a yes: /gmf bank share on shows your bank snapshot to the {leader}'s side by whisper. Off takes it back.",
			long = "Only if your guild master or an officer says yes. /gmf bank share on shows your bank's snapshot to the {leader} and the {helpers}, by whisper, never on the channel. /gmf bank share off takes it back." },
		{ id = "feat-donations", topic = "features",
			q = { "How do I know where to donate?", "What's 'taking donations'?" },
			text = "When a keeper takes donations, a line on {guildTab} and Treasury tabs says who and where.",
			long = "When a keeper types /gmf donations on, everyone sees a line on {guildTab} and Treasury tabs saying they're taking donations, with their zone if they share it. It goes off when they log out." },
		{ id = "feat-backup", topic = "features",
			q = { "My settings reset, can I save them?", "What's /gmf backup?" },
			text = "Type /gmf backup to copy your settings as text. Keep it; /gmf restore brings it back after a wipe.",
			long = "/gmf backup copies your settings (and a keeper's treasury book) as text: keep it in a file. If your settings ever come back empty, /gmf restore pastes it back. Nothing is uploaded, and it never holds the channel key." },
		{ id = "feat-world-map", topic = "features",
			q = { "How do I see the {members} on the map?", "How do I turn off the map circles?" },
			text = "The map shows {members} per zone. The round Guild Master Forever button (bottom left of the map) or /gmf map turns it on or off.",
			long = "The world map shows {members} per zone and continent, call icons, the {leader}'s crown and camps. The round Guild Master Forever button at the bottom left of the map turns them on or off; /gmf map too. In gamepad mode only continent totals show." },
		{ id = "feat-guildmate-dots", topic = "features",
			q = { "How do I see guildmates on the map?", "How do I share my position with my guild?" },
			text = "Type /gmf share to share your spot with your guild; /gmf mates shows guildmates on your map.",
			long = "Off by default. /gmf share shares your position with your guild, and /gmf mates shows guildmates' dots on your map and minimap. It stays inside your guild." },
		{ id = "feat-borders-nameplates", topic = "features",
			q = { "What are the gold wings on portraits?", "What's the star on nameplates?", "How do I turn them off?" },
			text = "Portrait borders and nameplate marks show guild roles. /gmf borders off or /gmf nameplates off hides them.",
			long = "Elite borders show a player's role on your target and focus portraits: gold wings for the {leader}, silver wings for the {moderators} (moderators), gold for {officers} and {helpers}, silver for Raiders, bronze wings for {guildmasters}, bronze for Veterans. Nameplates get small marks (a star for members). /gmf borders off or /gmf nameplates off hides them." },
		{ id = "feat-alt-links", topic = "features",
			q = { "How do I link my alts?", "Why does my alt count twice?" },
			text = "Type /gmf alt add Name on your main, then say yes on the alt.",
			long = "/gmf alt add Name on your main, then log that alt and say yes, and the census and treasury count you once." },
		{ id = "feat-help-status", topic = "features",
			q = { "What are the commands?", "How do I use this addon?", "Where's the help?" },
			text = "Help button left of the X, or /gmf help for all commands. /gmf status shows diagnostics.",
			long = "Click the help button left of the window's X: what each tab is for, privacy switches, links and Report a bug. /gmf help lists every command, and /gmf status shows what your addon knows." },
		{ id = "feat-search", topic = "features",
			q = { "Can I search the lists?", "How do I find a name on a tab?" },
			text = "Most tabs have a search box on top. It only filters what you see.",
			long = "The {censusTab}, {guildTab}, {tabardsTab}, Treasury, {callsTab} and Chat tabs have a search box: guilds, {guildmasters}, players or zones on the {censusTab}, members on {guildTab}, guildmates on {tabardsTab}, donors and bank items on the Treasury, the log on {callsTab}, lines on Chat. It only filters what you see." },
		{ id = "feat-open-window", topic = "features",
			q = { "How do I open Guild Master Forever?", "Where's the window?" },
			text = "Type /gmf, or click the minimap button or the round button in your guild window.",
			long = "Type /gmf, click the minimap button, or the round button in your guild window. Shift-click the minimap button for the Chat tab; right-click it to show or hide the map markers." },
		{ id = "feat-gamepad", topic = "features",
			q = { "Does it work with a controller?", "The game froze in gamepad mode" },
			text = "With the gamepad UI Guild Master Forever uses its own windows. If the game blocks something, /reload, then report it from the help button.",
			long = "Yes. With Blizzard's gamepad UI, Guild Master Forever asks in its own windows (answer with the cursor) and leaves the world map alone. If the game blocks something, /reload clears it; report it from the help button, not /gmf bug." },
		{ id = "feat-languages", topic = "features",
			q = { "Is it in Portuguese or Spanish?", "How do I change the language?" },
			text = "It follows your game language: English and Portuguese in full, Spanish, French and German for the main screens. Page help is in English.",
			long = "It follows your game language. English and Portuguese are complete; Spanish, French and German cover the main screens. The pages' ? help and the Answers are in English for now. Only what's on your screen changes." },
		{ id = "feat-key-block", topic = "features",
			q = { "How do I seal the channel?", "How do I ignore someone in Guild Master Forever?" },
			text = "Officers: /gmf key <secret> (same as other guilds) seals the channel. /gmf block <name> ignores a player.",
			long = "Officers: /gmf key <secret> seals the network channel so outsiders can't join. Use the same secret as the other guilds of the network or your guild splits off. /gmf block <name> ignores everything a player sends." },
		{ id = "feat-discord-link", topic = "features",
			q = { "How do I get my Discord role?", "What's /gmf discord?" },
			text = "Discord Link (Discord roles) isn't open yet: it comes with a later update of the addon.",
			long = "Discord Link will prove your character to the Discord bot on Discord for your role, but it isn't open yet: it needs a later addon update. Until then /gmf discord just says it's not open." },
		{ id = "feat-issue-reporter", topic = "features",
			q = { "How do I hide Blizzard's Issue Reporter box?", "What's that Issue Reporter window at login?" },
			text = "Click Hide on the box or /gmf issuereporter hide. If it comes back after a relog, hide it again.",
			long = "Click Hide on the box, or type /gmf issuereporter hide; /gmf issuereporter show brings it back. If it comes back after a relog, hide it again. With the gamepad UI Guild Master Forever leaves it alone." },
		{ id = "feat-workshop", topic = "features",
			q = { "What's the Workshop tab?", "Why did I get a roll call?" },
			text = "The author's tab for versions and bug reports. You answer roll calls only if you said yes; /gmf rollcall off stops them.",
			long = "The author's own tab: roll calls for versions and errors, asking out-of-date players to update, and bug reports players send them. Only they have it. You answer roll calls only if you said yes; /gmf rollcall off stops them." },
		{ id = "feat-page-help", topic = "features",
			q = { "What does the ? on a page do?", "Where's the explanation of this page?" },
			text = "The ? in each page's bottom box (by the gear on the Chat tab) explains that page and why its counts can differ.",
			long = "Each page has a ? in its bottom box (next to the gear on the Chat tab): it explains that page and, where it shows counts, why they can differ between players. The help button left of the X is the general help." },
		{ id = "feat-quick-answers", topic = "features",
			q = { "What's the Answers button?", "How do moderators answer questions so fast?" },
			text = "The author, {moderators} and {officers} have an Answers button: a click puts a ready answer in the box to edit, nothing is sent by itself.",
			long = "The author and the {moderators} get an Answers button at the end of the Chat tab's box and in the add-on's whisper window: short ready answers by topic, searchable. A click puts one in the box to edit; nothing is sent until you do." },
		{ id = "help-install", topic = "install-update-bugs",
			q = { "How do I install Guild Master Forever?", "Where do I get the addon?" },
			text = "Get Guild Master Forever in the CurseForge app or WowUp (pick the Forever install), then restart the game.",
			long = "Get Guild Master Forever in the CurseForge app or WowUp and pick your Forever game install, not Classic Era. Then restart the game. By hand: unzip it so you end up with Interface > AddOns > GuildMasterForever > GuildMasterForever.toc." },
		{ id = "help-update", topic = "install-update-bugs",
			q = { "How do I update?", "I updated but nothing changed" },
			text = "Update in the CurseForge app or WowUp, then close and reopen the game (a /reload isn't enough).",
			long = "Update Guild Master Forever in the CurseForge app or WowUp, then close and reopen the game: a /reload won't load a new version properly. /gmf status shows your version on its first line." },
		{ id = "help-check-version", topic = "install-update-bugs",
			q = { "Which version do I have?", "Am I up to date?" },
			text = "Type /gmf status: the first line is your version, and a later line says if a newer one is out.",
			long = "Type /gmf status: the first line shows your version, and a later line shows the latest release your addon heard of and whether you're behind." },
		{ id = "help-old-version", topic = "install-update-bugs",
			q = { "Do I have to update?", "My version is old, does it matter?" },
			text = "Please update: old versions drop what new ones send, and your guild can look broken to others. CurseForge or WowUp, then restart.",
			long = "Please do. Older versions drop what newer ones send, so your census can look off and your guild can look broken to everyone else. Update in the CurseForge app or WowUp, then restart the game." },
		{ id = "help-out-of-date", topic = "install-update-bugs",
			q = { "The AddOns list says 'out of date'", "Guild Master Forever is disabled as out of date" },
			text = "That's the game's patch check, not Guild Master Forever. Tick Load out of date AddOns in the AddOns list.",
			long = "That's the game comparing against its own patch number, not the add-on's version. Tick Load out of date AddOns in the AddOns list and it loads." },
		{ id = "help-author-update-popup", topic = "install-update-bugs",
			q = { "I got a window saying the author asks me to update", "Is the update popup legit?" },
			text = "If it says the author asks, it's real: only their character can send it, and only if you're behind. Update and restart. /gmf rollcall off stops theirs.",
			long = "If it says the author of the addon asks you, it's real: only their character can send it, and only when your version is older than the one they released. Update in the CurseForge app or WowUp, then restart. /gmf rollcall off stops theirs. One naming a player is that player's ask." },
		{ id = "help-report-bug", topic = "install-update-bugs",
			q = { "Where do I report a bug?", "How do I send the author an error?" },
			text = "Guild Master Forever window, help button (left of the X), Report a bug (or /gmf bug). Paste it in a new issue on the add-on's GitHub page.",
			long = "Open the Guild Master Forever window, click the help button left of the X, then Report a bug (or type /gmf bug). Press Ctrl+C, then paste it in a new issue at github.com/swiftyPigeon/Guild_Master_Forever/issues, with a line on what you were doing. The address is at the top of the report and on the help page." },
		{ id = "help-blocked", topic = "install-update-bugs",
			q = { "The game says it blocked Guild Master Forever", "I got an 'action blocked' error" },
			text = "A /reload clears it. Then report it: Guild Master Forever window, help button, Report a bug (not /gmf bug with the gamepad).",
			long = "A /reload clears it. Then tell us what happened: Guild Master Forever window, help button, Report a bug. With the gamepad UI, don't type /gmf bug in chat; use the button, since a typed command can set the block off again." },
		{ id = "help-settings-reset", topic = "install-update-bugs",
			q = { "My settings reset every login", "Why do I keep getting asked the same questions?" },
			text = "If your settings come back empty after a login, /gmf restore brings back what /gmf backup saved; privacy answers are asked again.",
			long = "If the game ever forgets addon data at login, your settings and privacy answers reset. /gmf backup saves your settings as text and /gmf restore puts them back, but not your privacy answers: those get asked again." },
		{ id = "help-safe", topic = "install-update-bugs",
			q = { "Is it safe? What does it send?", "Does the addon send my data anywhere?" },
			text = "It only uses the game's addon messages, no outside server. Location, chats and the rest wait for your yes (/gmf privacy).",
